/* ── Monthly time-series bars (SVG) ───────────────────────────────────── */
(function buildTimeSeries() {
  const svg = document.getElementById('ts-svg');
  const ns = 'http://www.w3.org/2000/svg';
  const W = 880, H = 220;
  const MARGIN = { l: 8, r: 8, t: 24, b: 36 };
  const chartW = W - MARGIN.l - MARGIN.r;
  const chartH = H - MARGIN.t - MARGIN.b; // 160px drawable
  const ZERO_FRAC = 0.72; // zero line at 72% from top (positive zone above, negative below)
  const zeroY = MARGIN.t + chartH * ZERO_FRAC; // y-coordinate of zero line
  const posZone = chartH * ZERO_FRAC;   // px available for positives
  const negZone = chartH * (1 - ZERO_FRAC); // px available for negatives
  const MAX_ABS = Math.max(...monthly.map(m => Math.abs(m.exc60)));
  const scale = v => Math.abs(v) / (MAX_ABS * 1.05); // fraction of zone to fill

  const n = monthly.length;
  const colW = chartW / n;
  const barW = Math.max(colW * 0.7, 10);

  // Backfill shading (first 9 months)
  const shadeW = colW * 9;
  const shade = document.createElementNS(ns, 'rect');
  shade.setAttribute('x', MARGIN.l);
  shade.setAttribute('y', MARGIN.t);
  shade.setAttribute('width', shadeW);
  shade.setAttribute('height', chartH);
  shade.setAttribute('fill', 'rgba(107,132,156,0.07)');
  svg.appendChild(shade);

  // In-sample label
  const il = document.createElementNS(ns, 'text');
  il.setAttribute('x', MARGIN.l + 4);
  il.setAttribute('y', MARGIN.t + 11);
  il.setAttribute('font-family', 'Courier New, monospace');
  il.setAttribute('font-size', '8');
  il.setAttribute('fill', '#6B849C');
  il.setAttribute('opacity', '0.6');
  il.setAttribute('letter-spacing', '0.12em');
  il.textContent = 'IN-SAMPLE';
  svg.appendChild(il);

  // Zero line
  const zl = document.createElementNS(ns, 'line');
  zl.setAttribute('x1', MARGIN.l); zl.setAttribute('x2', W - MARGIN.r);
  zl.setAttribute('y1', zeroY);   zl.setAttribute('y2', zeroY);
  zl.setAttribute('stroke', '#1A2F50'); zl.setAttribute('stroke-width', '1');
  svg.appendChild(zl);

  // Bars
  monthly.forEach((m, i) => {
    const cx = MARGIN.l + colW * i + colW / 2;
    const isPos = m.exc60 >= 0;
    const frac = scale(m.exc60);
    const px = (isPos ? posZone : negZone) * frac;
    const clr = m.live
      ? (isPos ? '#5B809A' : '#C05050')
      : (isPos ? 'rgba(91,128,154,0.38)' : 'rgba(192,80,80,0.28)');

    const rect = document.createElementNS(ns, 'rect');
    rect.setAttribute('x', cx - barW / 2);
    rect.setAttribute('width', barW);
    rect.setAttribute('fill', clr);
    rect.setAttribute('rx', '1.5');

    if (isPos) {
      rect.setAttribute('y', zeroY - px);
      rect.setAttribute('height', px);
    } else {
      rect.setAttribute('y', zeroY);
      rect.setAttribute('height', px);
    }
    svg.appendChild(rect);

    // Date label
    const lbl = document.createElementNS(ns, 'text');
    lbl.setAttribute('x', cx);
    lbl.setAttribute('y', H - MARGIN.b + 12);
    lbl.setAttribute('font-family', 'Courier New, monospace');
    lbl.setAttribute('font-size', '7.5');
    lbl.setAttribute('fill', '#6B849C');
    lbl.setAttribute('text-anchor', 'middle');
    lbl.setAttribute('transform', `rotate(-40 ${cx} ${H - MARGIN.b + 12})`);
    lbl.textContent = m.d;
    svg.appendChild(lbl);
  });

  // Backfill border right edge
  const bl = document.createElementNS(ns, 'line');
  bl.setAttribute('x1', MARGIN.l + colW * 9); bl.setAttribute('x2', MARGIN.l + colW * 9);
  bl.setAttribute('y1', MARGIN.t); bl.setAttribute('y2', MARGIN.t + chartH);
  bl.setAttribute('stroke', '#1A2F50'); bl.setAttribute('stroke-width', '1');
  bl.setAttribute('stroke-dasharray', '3,3');
  svg.appendChild(bl);
})();

